```javascript
function handleClusterTestProcess() {
  setConnTest(false)
  setModalMessage("")

  // 1. API 호출: POST /elasticsearch/status
  dispatch(setClusterStatus({ 
    name, host, port, scheme, username, password 
  }))
    .then(status => {
      // 2. 응답 검증
      if (!status['connection']) {
        setConnTest(false)
        setModalMessage("연결 실패")
        return
      }

      // 3. 성공 시 노드 수 계산
      setConnTest(true)
      const nodeSize = Object.values(status['nodes'])
        .map(node => {
          const tmp = (node['http'] || node['http']) || {}
          return tmp['publish_address'] 
            ? `${scheme}://${tmp['publish_address']}` 
            : null
        })
        .filter(addr => addr !== null)
        .length

      setModalMessage("[연결 성공] 노드 수:" + nodeSize)
    })
    .catch(error => {
      setConnTest(false)
      setModalMessage("연결 실패")
      console.error(error)
    })
}
```

